package dev.aero;

import java.util.*;
import net.minecraft.block.*;
import net.minecraft.util.math.*;
import static dev.aero.AeroMod.*;

/** Nine authored room roles, composed by a validated graph. Home is never regenerated by a trip. */
public final class AeroSectorBuilder {
    public static final int STEP=28, WIDTH=24;
    public static final BlockPos HOME=new BlockPos(0,180,0), SECTOR=HOME.add(112,0,-8);
    public static final BlockPos NAV=HOME.add(6,2,-7), SHOP=HOME.add(46,2,121);
    private final List<AeroBuild.Placement> work=new ArrayList<>();
    private final BlockPos at;
    private AeroSectorBuilder(BlockPos at){this.at=at;}
    private void put(int x,int y,int z,BlockState state){work.add(new AeroBuild.Placement(at.add(x,y,z),state));}
    private void put(int x,int y,int z,Block block){put(x,y,z,block.getDefaultState());}
    private void box(int x0,int y0,int z0,int x1,int y1,int z1,Block block){for(int y=y0;y<=y1;y++)for(int z=z0;z<=z1;z++)for(int x=x0;x<=x1;x++)put(x,y,z,block);}
    private void tree(int x,int y,int z,int r){box(x,y,z,x,y+3,z,SILVER);box(x-r,y+3,z-r,x+r,y+5,z+r,LEAF);box(x-1,y+6,z-1,x+1,y+6,z+1,LEAF);}
    public static BlockPos room(int id){return SECTOR.add(id%3*STEP,0,id/3*STEP);}
    public static BlockPos valve(int room,int index,int size){int start=10;return room(room).add(start+(index%size),1,start+(index/size));}
    public static BlockPos sample(int room,int theme){return room(room).add(18,theme==1?5:2,17);}
    public static BlockPos exit(){return room(8).add(20,2,20);}
    public static BlockState valveState(CircuitPlan plan,int index,int rotation,boolean lit){
        int mask=plan.shapeMask(index);boolean elbow=mask!=5&&mask!=10;int base=elbow?3:5,offset=0;
        while(CircuitPlan.rotateMask(base,offset)!=mask&&offset<4)offset++;
        return VALVE.getDefaultState().with(AeroValveBlock.ELBOW,elbow).with(AeroValveBlock.ROTATION,(rotation+offset)&3).with(AeroValveBlock.LIT,lit);
    }
    public static List<AeroBuild.Placement> hub(){
        var result=new ArrayList<>(AeroWorld.plan(HOME));var b=new AeroSectorBuilder(HOME);
        b.box(5,1,-8,7,1,-6,WHITE);b.put(6,2,-7,NAVIGATOR);b.put(6,3,-7,LAMP);
        // A small working example teaches the same port shapes used on journeys.
        b.put(-8,1,-4,BLUE);b.put(-7,1,-4,VALVE.getDefaultState().with(AeroValveBlock.ROTATION,1).with(AeroValveBlock.LIT,true));
        b.put(-6,1,-4,VALVE.getDefaultState().with(AeroValveBlock.ELBOW,true).with(AeroValveBlock.ROTATION,2).with(AeroValveBlock.LIT,true));
        b.put(-6,1,-3,VALVE.getDefaultState().with(AeroValveBlock.ELBOW,true).with(AeroValveBlock.LIT,true));b.put(-5,1,-3,AQUA);
        b.box(30,0,119,47,0,123,TILE);b.box(34,1,119,34,3,123,Blocks.AIR);
        b.box(39,1,118,47,1,118,WHITE);b.box(39,1,124,47,1,124,WHITE);
        b.box(43,0,117,48,0,124,TILE);b.put(46,2,121,WORKSHOP);b.box(45,1,120,47,1,122,WHITE);b.put(46,3,121,LAMP);
        result.addAll(b.work);result.addAll(garden(0,18));return result;
    }
    public static List<AeroBuild.Placement> garden(int oldSize,int size){
        var b=new AeroSectorBuilder(HOME);int x0=48,z0=126;
        // Expansion touches only its reserved rail and new land, retaining every old editable block.
        if(oldSize>0){b.box(x0+oldSize,1,z0-1,x0+oldSize,2,z0+oldSize,Blocks.AIR);b.box(x0-1,1,z0+oldSize,x0+oldSize,2,z0+oldSize,Blocks.AIR);}
        for(int x=oldSize==0?-1:oldSize;x<=size;x++)for(int z=-1;z<=size;z++)b.land(x0,z0,x,z,size);
        if(oldSize>0)for(int x=-1;x<oldSize;x++)for(int z=oldSize;z<=size;z++)b.land(x0,z0,x,z,size);
        b.box(x0-1,1,z0-1,x0+size,2,z0-1,Blocks.GLASS);b.box(x0-1,1,z0-1,x0-1,2,z0+size,Blocks.GLASS);
        b.box(x0+size,1,z0-1,x0+size,2,z0+size,Blocks.GLASS);b.box(x0-1,1,z0+size,x0+size,2,z0+size,Blocks.GLASS);
        b.box(48,0,121,51,0,126,TILE);b.box(48,1,125,51,2,125,Blocks.AIR);
        if(oldSize==0){b.tree(61,1,137,2);b.box(54,-1,133,57,-1,136,AQUA);b.box(54,0,133,57,0,136,Blocks.WATER);}
        return b.work;
    }
    private void land(int x0,int z0,int x,int z,int size){put(x0+x,-2,z0+z,WHITE);put(x0+x,-1,z0+z,WHITE);put(x0+x,0,z0+z,x>=0&&x<size&&z>=0&&z<size?Blocks.GRASS_BLOCK:TILE);}
    public static List<AeroBuild.Placement> expedition(ExpeditionPlan plan,AeroState.Book state){
        var b=new AeroSectorBuilder(SECTOR);
        b.box(-2,0,-2,82,19,82,Blocks.AIR);
        b.box(-3,-2,-3,83,-2,83,AQUA);b.box(-3,-1,-3,83,0,83,Blocks.WATER);
        for(int id=0;id<9;id++)b.room(plan,id,state);
        // Corridors visibly expose only the edges selected by the graph.
        for(int id=0;id<9;id++){
            int x=id%3*STEP,z=id/3*STEP,edges=plan.connections(id);
            if((edges&2)!=0){b.box(x+23,0,z+10,x+28,0,z+13,TILE);b.box(x+24,1,z+9,x+27,3,z+9,Blocks.GLASS);b.box(x+24,1,z+14,x+27,3,z+14,Blocks.GLASS);}
            if((edges&4)!=0){b.box(x+10,0,z+23,x+13,0,z+28,TILE);b.box(x+9,1,z+24,x+9,3,z+27,Blocks.GLASS);b.box(x+14,1,z+24,x+14,3,z+27,Blocks.GLASS);}
        }
        return b.work;
    }
    private void room(ExpeditionPlan plan,int id,AeroState.Book state){
        int x=id%3*STEP,z=id/3*STEP,theme=plan.theme();int h=theme==1?17:theme==2?8:13;
        var kind=plan.roomKind(id);if(kind==ExpeditionPlan.RoomKind.OVERLOOK)h=17;
        box(x,0,z,x+23,0,z+23,TILE);box(x,1,z,x+23,h,z,WHITE);box(x,1,z+23,x+23,h,z+23,WHITE);
        box(x,1,z,x,h,z+23,WHITE);box(x+23,1,z,x+23,h,z+23,WHITE);
        for(int a=3;a<=18;a+=5){box(x+a,3,z,x+a+3,h-2,z,Blocks.GLASS);box(x+a,3,z+23,x+a+3,h-2,z+23,Blocks.GLASS);box(x,3,z+a,x,h-2,z+a+3,Blocks.GLASS);box(x+23,3,z+a,x+23,h-2,z+a+3,Blocks.GLASS);}
        box(x,h+1,z,x+23,h+1,z+23,theme==2?WHITE:Blocks.GLASS);
        for(int a=0;a<=23;a+=5){box(x+a,h+1,z,x+a,h+1,z+23,WHITE);box(x,h+1,z+a,x+23,h+1,z+a,WHITE);}
        box(x+1,1,z+1,x+1,2,z+22,theme==1?GREEN:BLUE);box(x+22,1,z+1,x+22,2,z+22,theme==1?GREEN:BLUE);
        for(int a:new int[]{3,20}){box(x+a,1,z+3,x+a,h,z+3,WHITE);put(x+a,h-1,z+4,LAMP);}
        int mask=plan.connections(id);
        if((mask&1)!=0)box(x+10,1,z,x+13,5,z,Blocks.AIR);
        if((mask&2)!=0)box(x+22,1,z+10,x+23,5,z+13,Blocks.AIR);
        if((mask&4)!=0)box(x+10,1,z+23,x+13,5,z+23,Blocks.AIR);
        if((mask&8)!=0)box(x,1,z+10,x+1,5,z+13,Blocks.AIR);
        if(kind==ExpeditionPlan.RoomKind.FLOW){
            CircuitPlan circuit=plan.puzzle(id);int[] rotations=state.rotations.get(id);if(rotations==null){rotations=new int[circuit.tileCount()];for(int i=0;i<rotations.length;i++)rotations[i]=circuit.initialRotation(i);state.rotations.put(id,rotations);}
            boolean[] flow=circuit.flow(rotations);int start=10;
            box(x+start-1,0,z+start-1,x+start+circuit.size(),0,z+start+circuit.size(),SILVER);
            for(int i=0;i<circuit.tileCount();i++){BlockPos p=valve(id,i,circuit.size()).subtract(SECTOR);put(p.getX(),p.getY(),p.getZ(),valveState(circuit,i,rotations[i],flow[i]));}
            put(x+start-1,1,z+start,BLUE);put(x+start-2,1,z+start,LAMP);
            int end=start+circuit.size()-1;put(x+end+1,1,z+end,AQUA);put(x+end+2,1,z+end,state.solved.contains(id)?LAMP:WHITE);
            box(x+19,-1,z+6,x+21,-1,z+18,AQUA);box(x+19,0,z+6,x+21,0,z+18,state.solved.contains(id)?Blocks.WATER:Blocks.GLASS);
            put(x+20,1,z+19,state.solved.contains(id)?LAMP:CONTROL);
        }else if(kind==ExpeditionPlan.RoomKind.STEPPING){
            box(x+4,-1,z+5,x+19,-1,z+19,AQUA);box(x+4,0,z+5,x+19,0,z+19,Blocks.WATER);
            for(int a=5;a<=17;a+=3){int y=theme==1?1+((a-5)/3)%2:1;box(x+a,y,z+11,x+a+1,y,z+12,WHITE);}
            // Broad safe banks and stairs mean a missed jump never invalidates a trip.
            box(x+3,0,z+9,x+4,0,z+14,TILE);box(x+19,0,z+9,x+20,0,z+14,TILE);
            put(x+10,1,z+5,LAMP);put(x+10,1,z+19,LAMP);
        }else if(kind==ExpeditionPlan.RoomKind.SPECIMEN){
            box(x+4,0,z+5,x+8,0,z+19,Blocks.MOSS_BLOCK);tree(x+6,1,z+8,2);
            box(x+14,0,z+14,x+20,0,z+20,Blocks.GRASS_BLOCK);
            if(theme==1){box(x+13,4,z+13,x+21,4,z+21,TILE);for(int a=0;a<4;a++)box(x+10+a,1+a,z+18,x+10+a,1+a,z+20,WHITE);tree(x+19,5,z+19,2);}
            BlockPos p=sample(id,theme).subtract(SECTOR);put(p.getX(),p.getY()-1,p.getZ(),WHITE);
            put(p.getX(),p.getY(),p.getZ(),state.sampled.contains(id)?Blocks.FLOWERING_AZALEA:SPECIMEN);
        }else if(kind==ExpeditionPlan.RoomKind.OVERLOOK){
            box(x+5,0,z+5,x+18,0,z+18,AQUA);box(x+6,0,z+6,x+17,0,z+17,Blocks.WATER);box(x+10,0,z+4,x+13,0,z+20,TILE);
            if(Math.floorMod(plan.seed(),11)==0){box(x+7,11,z+7,x+16,12,z+16,LEAF);box(x+11,8,z+11,x+11,11,z+11,SILVER);put(x+11,7,z+11,LAMP);}
            else {tree(x+5,1,z+6,2);tree(x+18,1,z+18,2);}
        }else {put(x+5,2,z+5,NAVIGATOR);box(x+4,1,z+4,x+6,1,z+6,WHITE);tree(x+18,1,z+6,2);}
        if(id==8){box(x+19,1,z+19,x+21,1,z+21,WHITE);put(x+20,2,z+20,NAVIGATOR);put(x+20,3,z+20,LAMP);}
    }
}
